t><rect x="505.0" y="250" width="130" height="58" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="570" y="277" text-anchor="middle" font-weight="700" fill="#0B7F5C">{$approve}</text><text x="570" y="297" text-anchor="middle" font-size="13" fill="#0B7F5C">{$p3}</text><text x="20" y="300" font-size="13" fill="#5E5B85">max_depth = 2</text></svg>
