L270 177z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><path d="M330 259L340 277L320 277z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><path d="M245 119L255 137L235 137z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><path d="M380 69L390 87L370 87z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><path d="M270 94L280 112L260 112z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><rect x="229" y="159" width="22" height="22" rx="4" fill="#1E1C52"/><text x="240" y="175" text-anchor="middle" font-size="15" font-weight="700" fill="#FFFFFF">?</text><text x="430" y="50" font-weight="700">k = 5</text><circle cx="442" cy="84" r="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="462" y="89">{$classA}: 2</text><path d="M442 113L452 131L432 131z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="462" y="129">{$classB}: 3</text><rect x="430" y="160" width="190" height="90" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="446" y="190" font-size="14">{$verdict}</text><text x="446" y="222" font-weight="700" fill="#0B7F5C">{$classB}</text><text x="430" y="284" font-size="13" fill="#5E5B85">{$note}</text></svg>
