            Q('c2', L('Perché un albero di decisione è facile da spiegare?', 'Why is a decision tree easy to explain?'), [L('È una serie di domande sì/no', 'It is a series of yes/no questions'), L('Non usa dati', 'It uses no data'), L('È sempre perfetto', 'It is always perfect'), L('È una rete neurale', 'It is a neural network')], 0, L('Si può disegnare.', 'You can draw it.')),
            Q('c3', L('Che cosa limita `max_depth`?', 'What does `max_depth` limit?'), [L('La profondità dell’albero', 'The tree’s depth'), L('Il numero di dati', 'The amount of data'), L('Il tempo', 'Time'), L('Le classi', 'The classes')], 0, L('Meno domande, meno memorizzazione.', 'Fewer questions, less memorising.')),
        ], task('python', L('Crea un `DecisionTreeClassifier(max_depth=4)`, addestralo su `X_train`, `y_train` e stampa `accuracy_score` sul test.', 'Create a `DecisionTreeClassifier(max_depth=4)`, train it on `X_train`, `y_train` and print the `accuracy_score` on the test set.'), "from sklearn.tree import DecisionTreeClassifier\nfrom sklearn.metrics import accuracy_score", [re('(\w+)\s*=\s*DecisionTreeClassifier\s*\(\s*max_depth\s*=\s*4\s*\)', L('Albero di profondità 4', 'Depth-4 tree')), re('\.fit\s*\(\s*X_train\s*,\s*y_train\s*\)', L('Lo addestri', 'You train it')), re('print\s*\(\s*accuracy_score\s*\(\s*y_test\s*,\s*\w+\.predict\s*\(\s*X_test\s*\)\s*\)\s*\)', L('Stampi l’accuratezza sul test', 'You print test accuracy'))], '', "albero = DecisionTreeClassifier(max_depth=4)\nalbero.fit(X_train, y_train)\nprint(accuracy_score(y_test, albero.predict(X_test)))"), [
            dMatch(pMatch(), [['fit', L('Addestra', 'Trains')], ['predict', L('Prevede la classe', 'Predicts the class')], ['predict_proba', L('Probabilità per classe', 'Probability per class')], ['max_depth', L('Limite di domande', 'Question limit')], ['accuracy_score', L('Percentuale di risposte giuste', 'Share of right answers')]], L('Gli strumenti del classificatore.', 'The classifier’s tools.')),
            dBlanks(pFill(), "albero = DecisionTreeClassifier(max_depth=3)\nalbero.___(X_train, y_train)\nprob = albero.___(X_test)", ['fit', 'predict_proba'], ['train', 'probability', 'score'], L('Addestrare e chiedere le probabilità.', 'Train and ask for probabilities.')),
        ]),
        lesson('metrics', L('Metriche e overfitting', 'Metrics and overfitting'), [
            P('L’**accuratezza** può ingannare: se il 99% delle transazioni è lecito, un modello che dice sempre “lecito” è accurato al 99% e inutile. Per le classi rare si guardano **precisione** (dei positivi trovati, quanti sono veri) e **richiamo** (dei veri positivi, quanti ne trova).', '**Accuracy** can mislead: if 99% of transactions are legitimate, a model always saying “legitimate” is 99% accurate and useless. For rare classes you look at **precision** (of the positives found, how many are real) and **recall** (of the real positives, how many it finds).'),
            C('from sklearn.metrics import classification_report
print(classification_report(y_test, previsti))

print(albero.score(X_train, y_train))   # 1.00 sul train…
print(albero.score(X_test, y_test))     # 0.71 sul test → overfitting', 'python'),
            P('L’**overfitting** è quando il modello impara a memoria i dati di addestramento, rumore compreso, e generalizza male: voto altissimo sul train, basso sul test. Rimedi: modello più semplice, più dati, regolarizzazione.', '**Overfitting** is when the model memorises the training data, noise included, and generalises poorly: very high score on train, low on test. Remedies: a simpler model, more data, regularisation.'),
        ], [
            Q('m1', L('Perché l’accuratezza può ingannare?', 'Why can accuracy mislead?'), [L('Con classi sbilanciate premia chi dice sempre la classe comune', 'With unbalanced classes it rewards always saying the common class'), L('È sempre sbagliata', 'It is always wrong'), L('Funziona solo con le immagini', 'It only works with images'), L('Non si può calcolare', 'It cannot be computed')], 0, L('Il 99% può essere inutile.', '99% can be useless.')),
            Q('m2', L('Train 1.00 e test 0.71 indicano…', 'Train 1.00 and test 0.71 indicate…'), ['Overfitting', 'Underfitting', L('Un modello perfetto', 'A perfect model'), L('Dati mancanti', 'Missing data')], 0, L('Ha imparato a memoria.', 'It memorised.')),
            Q('m3', L('Il richiamo misura…', 'Recall measures…'), [L('Quanti veri positivi trova', 'How many real positives it finds'), L('La velocità', 'Speed'), L('Quanti dati usa', 'How much data it uses'), L('La memoria occupata', 'Memory used')], 0, L('Per le frodi conta molto.', 'For fraud it matters a lot.')),
        ], task('python', L('Stampa il punteggio del modello `albero` sul train e sul test con `.score()`, poi il `classification_report` delle previsioni `previsti`.', 'Print the `albero` model’s score on train and on test with `.score()`, then the `classification_report` of the predictions `previsti`.'), "from sklearn.metrics import classification_report", [re('print\s*\(\s*albero\.score\s*\(\s*X_train\s*,\s*y_train\s*\)\s*\)', L('Punteggio sul train', 'Train score')), re('print\s*\(\s*albero\.score\s*\(\s*X_test\s*,\s*y_test\s*\)\s*\)', L('Punteggio sul test', 'Test score')), re('print\s*\(\s*classification_report\s*\(\s*y_test\s*,\s*previsti\s*\)\s*\)', L('Il report completo', 'The full report'))], '', "print(albero.score(X_train, y_train))\nprint(albero.score(X_test, y_test))\nprint(classification_report(y_test, previsti))"), [
            dMatch(pMatch(), [[L('Accuratezza', 'Accuracy'), L('Quota di risposte giuste', 'Share of right answers')], [L('Precisione', 'Precision'), L('Positivi trovati che sono veri', 'Positives found that are real')], [L('Richiamo', 'Recall'), L('Veri positivi trovati', 'Real positives found')], ['Overfitting', L('Bene sul train, male sul test', 'Good on train, bad on test')]], L('Leggere le metriche.', 'Reading the metrics.')),
            dFlash(pFlash(), [[L('Un’accuratezza del 99% è sempre ottima', '99% accuracy is always great'), false], [L('Un modello più semplice può ridurre l’overfitting', 'A simpler model can reduce overfitting'), true], [L('Più dati aiutano a generalizzare', 'More data helps generalisation'), true], [L('L’overfitting dà voti bassi sul train', 'Overfitting gives low train scores'), false]], L('Il test dice la verità.', 'The test tells the truth.')),
        ]),
        lesson('knn', L('I vicini più vicini', 'Nearest neighbours'), [
            P('Il **k-nearest neighbours** (k-NN) è il modello più intuitivo: per classificare un nuovo esempio guarda i *k* esempi di addestramento più **vicini** e sceglie la classe più frequente tra loro. Non impara pesi: si ricorda i dati e misura distanze.', '**k-nearest neighbours** (k-NN) is the most intuitive model: to classify a new example it looks at the *k* **closest** training examples and picks the most frequent class among them. It learns no weights: it remembers the data and measures distances.'),
            Fig(L(fig_mlbase_knn('cerchi', 'triangoli', 'Previsione:', 'Decide la maggioranza.'), fig_mlbase_knn('circles', 'triangles', 'Prediction:', 'The majority decides.')),
                L('Una nuvola di punti di due classi, cerchi blu a sinistra e triangoli verdi a destra. Un nuovo esempio, un quadrato con il punto di domanda, è collegato ai suoi 5 vicini più prossimi dentro un cerchio tratteggiato: 3 triangoli e 2 cerchi, quindi diventa un triangolo.', 'A cloud of points of two classes, blue circles on the left and green triangles on the right. A new example, a square with a question mark, is linked to its 5 nearest neighbours inside a dashed circle: 3 triangles and 2 circles, so it becomes a triangle.'),
                L('Con k = 5 vince la classe più frequente tra i cinque punti più vicini.', 'With k = 5 the most frequent class among the five closest points wins.')),
            C('from sklearn.neighbors import KNeighborsClassifier
from sklearn.preprocessing import StandardScaler

scaler = StandardScaler().fit(X_train)        # media e deviazione dal solo train
knn = KNeighborsClassifier(n_neighbors=5)
knn.fit(scaler.transform(X_train), y_train)
print(knn.score(scaler.transform(X_test), y_test))', 'python'),
            P('Poiché usa le distanze, le caratteristiche vanno **scalate**: altrimenti il reddito in migliaia schiaccia l’età in anni. *k* piccolo segue ogni dettaglio (rischio di overfitting), *k* grande liscia troppo. Con milioni di esempi diventa lento, perché a ogni previsione confronta il nuovo punto con tutti.', 'Since it uses distances, features must be **scaled**: otherwise income in thousands crushes age in years. A small *k* follows every detail (risk of overfitting), a large *k* smooths too much. With millions of examples it gets slow, because every prediction compares the new point with all of them.'),
        ], [
            Q('n1', L('Come decide k-NN la classe di un nuovo esempio?', 'How does k-NN decide a new example’s class?'), [L('Con una formula imparata durante l’addestramento', 'With a formula learned during training'), L('A caso tra le classi possibili', 'At random among the possible classes'), L('Con la classe più frequente tra i k vicini', 'With the most frequent class among the k neighbours'), L('Scegliendo sempre la classe più rara', 'Always picking the rarest class')], 2, L('Vota il vicinato.', 'The neighbourhood votes.')),
            Q('n2', L('Perché scalare i dati prima di k-NN?', 'Why scale the data before k-NN?'), [L('Le distanze sarebbero dominate dalle colonne con numeri grandi', 'Distances would be dominated by columns with big numbers'), L('Per ridurre il numero di righe del dataset', 'To reduce the number of rows'), L('Perché k-NN accetta solo numeri negativi', 'Because k-NN only accepts negative numbers'), L('Non serve: k-NN ignora le unità di misura', 'No need: k-NN ignores units')], 0, L('Ogni colonna deve pesare in modo giusto.', 'Each column must weigh fairly.')),
            Q('n3', L('Che cosa succede con k = 1?', 'What happens with k = 1?'), [L('Il modello diventa più semplice e liscio', 'The model becomes simpler and smoother'), L('Segue ogni dettaglio e rischia l’overfitting', 'It follows every detail and risks overfitting'), L('Il modello non può fare previsioni', 'The model cannot make predictions'), L('Usa sempre la classe più frequente del dataset', 'It always uses the dataset’s most frequent class')], 1, L('Un solo vicino, anche se è rumore.', 'A single neighbour, even if it is noise.')),
        ], task('python', L('Crea un `KNeighborsClassifier` con `n_neighbors=3` in `knn` e addestralo su `X_train_s` e `y_train` (dati già scalati).', 'Create a `KNeighborsClassifier` with `n_neighbors=3` in `knn` and train it on `X_train_s` and `y_train` (already scaled data).'), "from sklearn.neighbors import KNeighborsClassifier", [re('knn\s*=\s*KNeighborsClassifier\s*\(\s*n_neighbors\s*=\s*3\s*\)', L('Tre vicini', 'Three neighbours')), re('knn\.fit\s*\(\s*X_train_s\s*,\s*y_train\s*\)', L('Lo addestri', 'You train it'))], '', "knn = KNeighborsClassifier(n_neighbors=3)\nknn.fit(X_train_s, y_train)"), [
            dMatch(pMatch(), [['k-NN', L('Votano i vicini', 'Neighbours vote')], ['n_neighbors', L('Quanti vicini', 'How many neighbours')], ['StandardScaler', L('Stessa scala per tutti', 'Same scale for all')], [L('k piccolo', 'Small k'), L('Rischio di overfitting', 'Risk of overfitting')]], L('Dimmi chi ti è vicino.', 'Tell me who is near you.')),
            dFlash(pFlash(), [[L('k-NN usa le distanze tra esempi', 'k-NN uses distances between examples'), true], [L('k-NN impara una matrice di pesi', 'k-NN learns a weight matrix'), false], [L('Con molti dati le previsioni di k-NN rallentano', 'With lots of data k-NN predictions slow down'), true], [L('Scalare i dati è inutile per k-NN', 'Scaling data is useless for k-NN'), false]], L('Vicinanza, non formule.', 'Closeness, not formulas.')),
        ]),
        lesson('confusion', L('Matrice di confusione e soglia', 'Confusion matrix and threshold'), [
            P('La **matrice di confusione** conta gli esiti di un classificatore: **veri positivi** (malati trovati), **falsi negativi** (malati sfuggiti), **falsi positivi** (allarmi inutili) e **veri negativi**. Da lì si calcolano precisione e richiamo.', 'The **confusion matrix** counts a classifier’s outcomes: **true positives** (sick people found), **false negatives** (sick people missed), **false positives** (needless alarms) and **true negatives**. Precision and recall are computed from it.'),
            Fig(L(fig_mlbase_confusion('classe prevista', 'classe vera', 'negativo', 'positivo', 'veri negativi', 'falsi positivi', 'falsi negativi', 'veri positivi', 'precisione', 'richiamo'), fig_mlbase_confusion('predicted class', 'actual class', 'negative', 'positive', 'true negatives', 'false positives', 'false negatives', 'true positives', 'precision', 'recall')),
                L('Una matrice due per due: righe per la classe vera, colonne per quella prevista. Veri negativi 850, falsi positivi 10, falsi negativi 30, veri positivi 110. La precisione si legge sulla colonna dei previsti positivi (110 su 120, circa 0,92), il richiamo sulla riga dei veri positivi (110 su 140, circa 0,79).', 'A two by two matrix: rows for the actual class, columns for the predicted one. True negatives 850, false positives 10, false negatives 30, true positives 110. Precision is read along the predicted-positive column (110 out of 120, about 0.92), recall along the actual-positive row (110 out of 140, about 0.79).'),
                L('Precisione: colonna dei positivi previsti. Richiamo: riga dei positivi veri.', 'Precision: the predicted-positive column. Recall: the actual-positive row.')),
            C('from sklearn.metrics import confusion_matrix

print(confusion_matrix(y_test, previsti))
# [[850  10]     veri negativi | falsi positivi
#  [ 30 110]]    falsi negativi | veri positivi
